// LAYER: SUPPORT — API wiring derived from OpenAPI files. Pure functions, no I/O, no AWS calls.
//
// Every API the solution calls (generated by the agent or supplied by the customer) has an OpenAPI file. From
// it this module derives, deterministically:
//   - the ACXD secrets: one base-URL secret per API and one credential secret per security scheme used,
//   - each data request's method, url and auth headers (matched to the OpenAPI operation by operationId),
//   - the API block of .env.example (between the `# >>> acxd-apis` / `# <<< acxd-apis` markers),
//   - the runbook's ".env update" bullets for the APIs.
// Credential VALUES never live in the OpenAPI file: they are read from .env into ACXD secrets.
//
// Supported security schemes: apiKey (header, query, cookie), http bearer, http basic, oauth2 and openIdConnect
// (sent as a current bearer token). http digest and mutualTLS cannot be expressed as a static header and are
// rejected. Base URLs never need a hand-trimmed trailing slash: the engine trims it when it creates the secret.
// Naming (no agent choice): API id from info.x-acxd-api-id, else from the file name; secrets
// <apiId>Url and <apiId>Key | Token | Basic; .env keys are the SCREAMING_SNAKE form of the secret name.

export type ApiKind = 'generated' | 'real';
export type CredentialKind = 'apiKeyHeader' | 'apiKeyQuery' | 'apiKeyCookie' | 'bearer' | 'basic' | 'oauth2';

export interface CredentialDef {
  scheme: string;           // securitySchemes key in the OpenAPI file
  kind: CredentialKind;
  paramName?: string;       // header / query / cookie name for apiKey
  secretName: string;
  envVar: string;
}
export interface WiredHeader { key: string; value: string; sensitive?: boolean }
export interface OperationWiring { operationId: string; method: string; url: string; headers: WiredHeader[]; credentials: string[] }
export interface ApiWiring {
  apiId: string;
  kind: ApiKind;
  urlSecret: string;
  urlEnvVar: string;
  serverUrl?: string;       // servers[0].url, cleaned; undefined if absent or a placeholder
  credentials: CredentialDef[];
  operations: OperationWiring[];
}

type Json = Record<string, any>;
const METHODS = ['get', 'post', 'put', 'patch', 'delete'];
const ID = /^[a-z][A-Za-z0-9]*$/;

export const ENV_BLOCK_START = '# >>> acxd-apis (generated from the OpenAPI files by openapi-wiring; do not edit inside these markers by hand)';
export const ENV_BLOCK_END = '# <<< acxd-apis';

/** camelCase -> SCREAMING_SNAKE (pricingApiKey -> PRICING_API_KEY). */
export function screaming(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase();
}
const pascal = (s: string) => s.replace(/[^A-Za-z0-9]+(.)?/g, (_, c) => (c ? c.toUpperCase() : '')).replace(/^./, (c) => c.toUpperCase());

/** API id: info.x-acxd-api-id, else the file name without "-openapi" and extension, camelCased, ending in "Api". */
export function apiIdOf(fileName: string, doc: Json): string {
  const declared = doc?.info?.['x-acxd-api-id'];
  if (typeof declared === 'string') {
    if (!ID.test(declared)) throw new Error(`info.x-acxd-api-id "${declared}" must be camelCase letters and digits.`);
    return declared;
  }
  const base = (fileName.split('/').pop() ?? fileName).replace(/\.(ya?ml|json)$/i, '').replace(/[-_.]?openapi$/i, '');
  const camel = pascal(base).replace(/^./, (c) => c.toLowerCase());
  const id = /Api$/.test(camel) ? camel : `${camel}Api`;
  if (!ID.test(id)) throw new Error(`cannot derive an API id from "${fileName}"; set info.x-acxd-api-id.`);
  return id;
}

/** 'generated' = an API this solution deploys (info.x-acxd-generated: true, CX Discovery options 2 and 3). */
export function apiKindOf(doc: Json): ApiKind {
  return doc?.info?.['x-acxd-generated'] === true ? 'generated' : 'real';
}

/** servers[0].url with trailing slashes trimmed; undefined when absent or a placeholder. */
export function cleanServerUrl(doc: Json): string | undefined {
  const u = doc?.servers?.[0]?.url;
  if (typeof u !== 'string' || !u.trim() || u.includes('{') || /REPLACE/i.test(u)) return undefined;
  return u.trim().replace(/\/+$/, '');
}

function credentialKind(name: string, s: Json): CredentialKind {
  const t = s?.type;
  if (t === 'apiKey') {
    if (s.in === 'header') return 'apiKeyHeader';
    if (s.in === 'query') return 'apiKeyQuery';
    if (s.in === 'cookie') return 'apiKeyCookie';
    throw new Error(`security scheme "${name}": apiKey needs "in" of header, query or cookie.`);
  }
  if (t === 'http') {
    const sc = String(s.scheme ?? '').toLowerCase();
    if (sc === 'bearer') return 'bearer';
    if (sc === 'basic') return 'basic';
    throw new Error(`security scheme "${name}": http "${s.scheme}" is not supported (ACXD data requests send static ` +
      'headers; digest needs a challenge-response). Use an adapter backend for this API.');
  }
  if (t === 'oauth2' || t === 'openIdConnect') return 'oauth2';
  if (t === 'mutualTLS') {
    throw new Error(`security scheme "${name}": mutualTLS is not supported by ACXD data requests. Use an adapter backend.`);
  }
  throw new Error(`security scheme "${name}": unknown type "${t}".`);
}
const SUFFIX: Record<CredentialKind, string> = {
  apiKeyHeader: 'Key', apiKeyQuery: 'Key', apiKeyCookie: 'Key', bearer: 'Token', oauth2: 'Token', basic: 'Basic',
};

function resolveRef(doc: Json, p: Json): Json {
  const ref = p?.$ref;
  if (typeof ref !== 'string' || !ref.startsWith('#/')) return p;
  return ref.slice(2).split('/').reduce((o: Json, k: string) => o?.[k], doc) ?? {};
}

/** Wire one API from its parsed OpenAPI document. Throws on an unsupported scheme or a missing operationId. */
export function wireApi(fileName: string, doc: Json): ApiWiring {
  const apiId = apiIdOf(fileName, doc);
  const kind = apiKindOf(doc);
  const urlSecret = `${apiId}Url`;
  const schemes: Json = doc?.components?.securitySchemes ?? {};

  // operations and the scheme(s) each uses (first alternative of its security requirement)
  const ops: Array<{ operationId: string; method: string; path: string; params: Json[]; schemes: string[] }> = [];
  for (const [path, item] of Object.entries((doc?.paths ?? {}) as Json)) {
    for (const m of METHODS) {
      const op = (item as Json)?.[m];
      if (!op) continue;
      if (typeof op.operationId !== 'string' || !op.operationId) {
        throw new Error(`${apiId}: ${m.toUpperCase()} ${path} has no operationId (each operation becomes one data request).`);
      }
      // The deployed API routes on one path segment equal to the operationId, so a generated API's path must be
      // exactly /{operationId}; any other path returns 404 at conversation time.
      if (kind === 'generated' && path !== `/${op.operationId}`) {
        throw new Error(`${apiId}: ${m.toUpperCase()} ${path} must be /${op.operationId}. An API this solution deploys ` +
          'routes on /{operationId}, so a generated OpenAPI file uses that path for every operation.');
      }
      if (kind === 'generated') {
        const body = resolveRef(doc, op?.requestBody?.content?.['application/json']?.schema ?? {});
        for (const [f, raw] of Object.entries((body?.properties ?? {}) as Json)) {
          const p = resolveRef(doc, raw);
          if (p?.type === 'object' && !p.properties) throw new Error(`${apiId}: ${op.operationId} request field "${f}" is an object with no properties. ` +
            'An API this solution deploys gives every value its own typed field, so each becomes one capture.');
          if (p?.type === 'array' && !p.items) throw new Error(`${apiId}: ${op.operationId} request field "${f}" is an array with no items type.`);
        }
      }
      const req = (op.security ?? doc.security ?? []) as Json[];
      const used = Object.keys(req[0] ?? {});
      for (const s of used) if (!schemes[s]) throw new Error(`${apiId}: ${op.operationId} uses security scheme "${s}", which is not in components.securitySchemes.`);
      const params = [...((item as Json).parameters ?? []), ...(op.parameters ?? [])].map((p: Json) => resolveRef(doc, p));
      ops.push({ operationId: op.operationId, method: m.toUpperCase(), path, params, schemes: used });
    }
  }

  // credentials for the schemes actually used
  const usedSchemes = [...new Set(ops.flatMap((o) => o.schemes))].sort();
  const kinds = new Map(usedSchemes.map((s) => [s, credentialKind(s, schemes[s])]));
  const suffixCount = new Map<string, number>();
  for (const k of kinds.values()) suffixCount.set(SUFFIX[k], (suffixCount.get(SUFFIX[k]) ?? 0) + 1);
  const credentials: CredentialDef[] = usedSchemes.map((s) => {
    const k = kinds.get(s) as CredentialKind;
    const secretName = (suffixCount.get(SUFFIX[k]) ?? 0) > 1 ? `${apiId}${pascal(s)}` : `${apiId}${SUFFIX[k]}`;
    return { scheme: s, kind: k, paramName: schemes[s].name, secretName, envVar: screaming(secretName) };
  }).sort((x, y) => x.secretName.localeCompare(y.secretName));
  const byScheme = new Map(credentials.map((c) => [c.scheme, c]));

  const operations: OperationWiring[] = ops.map((o) => {
    const creds = o.schemes.map((s) => byScheme.get(s) as CredentialDef);
    const query: string[] = o.params.filter((p) => p?.in === 'query' && p.required === true && p.name).map((p) => `${p.name}={${p.name}}`);
    const headers: WiredHeader[] = [];
    const cookies: string[] = [];
    for (const c of creds) {
      const tok = `{${c.secretName}:NLX.Secret}`;
      if (c.kind === 'apiKeyHeader') headers.push({ key: String(c.paramName), value: tok, sensitive: true });
      else if (c.kind === 'apiKeyQuery') query.push(`${c.paramName}=${tok}`);
      else if (c.kind === 'apiKeyCookie') cookies.push(`${c.paramName}=${tok}`);
      else if (c.kind === 'basic') headers.push({ key: 'Authorization', value: `Basic ${tok}`, sensitive: true });
      else headers.push({ key: 'Authorization', value: `Bearer ${tok}`, sensitive: true });
    }
    if (cookies.length) headers.push({ key: 'Cookie', value: cookies.join('; '), sensitive: true });
    const url = `{${urlSecret}:NLX.Secret}${o.path}${query.length ? `?${query.join('&')}` : ''}`;
    return { operationId: o.operationId, method: o.method, url, headers, credentials: creds.map((c) => c.secretName) };
  });

  return { apiId, kind, urlSecret, urlEnvVar: screaming(urlSecret), serverUrl: cleanServerUrl(doc), credentials, operations };
}

// ---------- resources (data-requests.json + secrets.json) ----------

export interface DataRequestLike { dataRequestId: string; implementation?: string; method?: string; url?: string; headers?: WiredHeader[]; [k: string]: unknown }
export interface SecretLike { name: string; envVar: string; description: string; isSensitive?: boolean }
const LEGACY_SECRETS = new Set(['mockApiUrl', 'mockApiKey']);

/** Set method/url/auth headers on every external data request from its OpenAPI operation; rebuild the API secrets. */
export function applyWiring(apis: ApiWiring[], dataRequests: DataRequestLike[], secrets: SecretLike[]):
  { dataRequests: DataRequestLike[]; secrets: SecretLike[]; problems: string[] } {
  const problems: string[] = [];
  const index = new Map<string, { api: ApiWiring; op: OperationWiring }>();
  for (const api of apis) for (const op of api.operations) {
    if (index.has(op.operationId)) problems.push(`operationId "${op.operationId}" appears in more than one OpenAPI file; operationIds must be unique.`);
    index.set(op.operationId, { api, op });
  }
  const used = new Map<string, Set<string>>(); // secretName -> data requests using it
  const mark = (s: string, dr: string) => { if (!used.has(s)) used.set(s, new Set()); used.get(s)!.add(dr); };
  const out = dataRequests.map((dr) => {
    if (dr.implementation !== 'external') return dr;
    const hit = index.get(dr.dataRequestId);
    if (!hit) {
      problems.push(`data request "${dr.dataRequestId}" has no operation with that operationId in any OpenAPI file. ` +
        'Name the data request after its operation, or add the operation to the API\'s OpenAPI file.');
      return dr;
    }
    const authKeys = new Set(['authorization', 'cookie', ...hit.api.credentials.filter((c) => c.kind === 'apiKeyHeader').map((c) => String(c.paramName).toLowerCase())]);
    const kept = (dr.headers ?? []).filter((h) => !authKeys.has(String(h.key).toLowerCase()) && !/NLX\.Secret/.test(String(h.value)));
    mark(hit.api.urlSecret, dr.dataRequestId);
    for (const s of hit.op.credentials) mark(s, dr.dataRequestId);
    const headers = [...kept, ...hit.op.headers];
    return { ...dr, method: hit.op.method, url: hit.op.url, ...(headers.length ? { headers } : { headers: undefined }) };
  });
  const generated: SecretLike[] = [];
  for (const api of [...apis].sort((a, b) => a.apiId.localeCompare(b.apiId))) {
    const users = (s: string) => [...(used.get(s) ?? [])].sort().join(', ') || 'none yet';
    generated.push({ name: api.urlSecret, envVar: api.urlEnvVar, isSensitive: false,
      description: `Base URL of ${api.apiId} (an endpoint, not a credential). Used by: ${users(api.urlSecret)}.` });
    for (const c of api.credentials) {
      generated.push({ name: c.secretName, envVar: c.envVar, isSensitive: true,
        description: `${CRED_LABEL[c.kind]} for ${api.apiId}. Used by: ${users(c.secretName)}.` });
    }
  }
  const names = new Set(generated.map((s) => s.name));
  const others = secrets.filter((s) => !names.has(s.name) && !LEGACY_SECRETS.has(s.name));
  return { dataRequests: out.map((d) => { if (d.headers === undefined) { const { headers: _h, ...r } = d; return r as DataRequestLike; } return d; }), secrets: [...generated, ...others], problems };
}
const CRED_LABEL: Record<CredentialKind, string> = {
  apiKeyHeader: 'API key', apiKeyQuery: 'API key', apiKeyCookie: 'API key', bearer: 'Bearer token', oauth2: 'OAuth access token', basic: 'Basic credentials',
};

// ---------- .env.example API block ----------

function credComment(api: ApiWiring, c: CredentialDef): string {
  const where = c.kind === 'apiKeyHeader' ? `header \`${c.paramName}\`` : c.kind === 'apiKeyQuery' ? `query parameter \`${c.paramName}\``
    : c.kind === 'apiKeyCookie' ? `cookie \`${c.paramName}\`` : 'the Authorization header';
  if (api.kind === 'generated' && c.kind.startsWith('apiKey')) {
    return `#   ${api.apiId}: API key (${where}). Generated in Backend Build; the Stage 1 stack sets it on API Gateway.`;
  }
  switch (c.kind) {
    case 'bearer': return `#   ${api.apiId}: a current bearer token, without the "Bearer " prefix (sent in ${where}).`;
    case 'oauth2': return `#   ${api.apiId}: a current OAuth access token, without the "Bearer " prefix (sent in ${where}). ` +
      'It expires: update it here and re-run Stage 2 when it does.';
    case 'basic': return `#   ${api.apiId}: base64 of user:password, without the "Basic " prefix (sent in ${where}).`;
    default: return `#   ${api.apiId}: your API key for this API (sent as ${where}). A credential: keep it here only.`;
  }
}
function urlComment(api: ApiWiring): string {
  if (api.kind === 'generated') {
    return `#   ${api.apiId} (deployed by this solution): base URL. Paste the Stage 1 \`${pascal(api.apiId)}Url\` output as shown.`;
  }
  return api.serverUrl
    ? `#   ${api.apiId}: base URL, pre-filled from the OpenAPI servers entry. Change it if your endpoint differs.`
    : `#   ${api.apiId}: base URL. The OpenAPI file has no server URL: enter your endpoint.`;
}

/** The API block, including its markers. `values` keeps values already entered (by .env key). */
export function renderEnvBlock(apis: ApiWiring[], values: Record<string, string> = {}): string {
  const lines = [ENV_BLOCK_START];
  const sorted = [...apis].sort((a, b) => a.apiId.localeCompare(b.apiId));
  sorted.forEach((api, i) => {
    if (i > 0) lines.push('');
    lines.push(urlComment(api));
    lines.push(`${api.urlEnvVar}=${values[api.urlEnvVar] ?? (api.kind === 'real' ? api.serverUrl ?? '' : '')}`);
    for (const c of api.credentials) {
      lines.push(credComment(api, c));
      lines.push(`${c.envVar}=${values[c.envVar] ?? ''}`);
    }
  });
  lines.push(ENV_BLOCK_END);
  return lines.join('\n');
}

function splitBlock(text: string): { before: string; inside: string; after: string } {
  const s = text.indexOf(ENV_BLOCK_START);
  const e = text.indexOf(ENV_BLOCK_END);
  if (s < 0 || e < 0 || e < s) throw new Error(`the .env file has no API block (lines "${ENV_BLOCK_START}" ... "${ENV_BLOCK_END}"). ` +
    'Copy .env.example from the shipped template exactly; it contains the empty block.');
  return { before: text.slice(0, s), inside: text.slice(s, e + ENV_BLOCK_END.length), after: text.slice(e + ENV_BLOCK_END.length) };
}
function blockValues(inside: string): Record<string, string> {
  const v: Record<string, string> = {};
  for (const l of inside.split('\n')) { const m = /^([A-Z0-9_]+)=(.*)$/.exec(l); if (m && m[2] !== '') v[m[1]] = m[2]; }
  return v;
}

/** Replace the API block in a .env / .env.example text, keeping any values already entered. */
export function fillEnvBlock(text: string, apis: ApiWiring[]): string {
  const { before, inside, after } = splitBlock(text);
  return before + renderEnvBlock(apis, blockValues(inside)) + after;
}

/** Drift check: outside the markers must equal the template; inside must equal the rendered block. */
export function checkEnvBlock(actual: string, template: string, apis: ApiWiring[]): string[] {
  const a = splitBlock(actual);
  const t = splitBlock(template);
  const problems: string[] = [];
  if (a.before !== t.before || a.after !== t.after) {
    problems.push('.env.example differs from the shipped template outside the API block. Copy the template exactly, then run openapi-wiring --env-example.');
  }
  if (a.inside !== renderEnvBlock(apis, blockValues(a.inside))) {
    problems.push('.env.example API block does not match the OpenAPI files. Re-run openapi-wiring --env-example; never edit inside the markers.');
  }
  return problems;
}

/** Fill blank API keys of generated APIs (40 characters, letters and digits). */
export function generateKeys(text: string, apis: ApiWiring[], random: (n: number) => string): { text: string; filled: string[] } {
  const filled: string[] = [];
  let out = text;
  for (const api of apis) {
    if (api.kind !== 'generated') continue;
    for (const c of api.credentials) {
      if (!c.kind.startsWith('apiKey')) continue;
      const re = new RegExp(`^${c.envVar}=(.*)$`, 'm');
      const m = re.exec(out);
      if (m && m[1] === '') { out = out.replace(re, `${c.envVar}=${random(40)}`); filled.push(c.envVar); }
    }
  }
  return { text: out, filled };
}

// ---------- runbook bullets (RULE 2b) ----------

export function renderRunbookBullets(apis: ApiWiring[]): string {
  const lines = ['Now update the following variables in `./.env`:', ''];
  for (const api of [...apis].sort((a, b) => a.apiId.localeCompare(b.apiId))) {
    if (api.kind === 'generated') {
      lines.push(`- \`${api.urlEnvVar}\`: the \`${pascal(api.apiId)}Url\` output of the mock APIs stack, as shown.`);
    } else {
      lines.push(api.serverUrl
        ? `- \`${api.urlEnvVar}\`: pre-filled from the ${api.apiId} OpenAPI file; change it if your endpoint differs.`
        : `- \`${api.urlEnvVar}\`: the ${api.apiId} base URL from your provider.`);
    }
    for (const c of api.credentials) {
      if (api.kind === 'generated' && c.kind.startsWith('apiKey')) {
        lines.push(`- \`${c.envVar}\`: check it is set (generated in Backend Build). Do not change it after the Stage 1 deploy.`);
      } else if (c.kind === 'bearer') {
        lines.push(`- \`${c.envVar}\`: a current bearer token for ${api.apiId}, without the "Bearer " prefix.`);
      } else if (c.kind === 'oauth2') {
        lines.push(`- \`${c.envVar}\`: a current OAuth access token for ${api.apiId}, without the "Bearer " prefix. It expires; update it and re-run Stage 2.`);
      } else if (c.kind === 'basic') {
        lines.push(`- \`${c.envVar}\`: base64 of user:password for ${api.apiId}, without the "Basic " prefix.`);
      } else {
        lines.push(`- \`${c.envVar}\`: your API key for ${api.apiId}, pasted whole.`);
      }
    }
  }
  return lines.join('\n');
}
